/**
 * The environment's default span retention.
 *
 * Separate from `tracingCorrelationConfigLogic`, which reads the same endpoint but only loads
 * when the person/session link flag is on — retention must load either way.
 */
export const tracingRetentionConfigLogic = kea<tracingRetentionConfigLogicType>([
    path(['products', 'tracing', 'frontend', 'components', 'TracingRetention', 'tracingRetentionConfigLogic']),

    loaders(() => ({
        tracingConfig: [
            null as TeamTracingConfigApi | null,
            {
                // The flat /api/projects/:team_id/ route is the canonical per-environment one.
                // The generated client only exposes the nested variant, whose viewset rejects
                // every request, so these URLs are deliberately hand-built (same as
                // tracingCorrelationConfigLogic).
                loadTracingConfig: async (): Promise<TeamTracingConfigApi> => {
                    // nosemgrep: prefer-codegen-api
                    return await api.get(`api/projects/${teamLogic.values.currentTeamId}/tracing_config/`)
                },
                updateRetentionDays: async (retentionDays: number): Promise<TeamTracingConfigApi> => {
                    const patch: PatchedTeamTracingConfigApi = { retention_days: retentionDays }
                    try {
                        // nosemgrep: prefer-codegen-api
                        const updated: TeamTracingConfigApi = await api.update(
                            `api/projects/${teamLogic.values.currentTeamId}/tracing_config/`,
                            patch
                        )
                        lemonToast.success('Traces retention updated')
                        return updated
                    } catch (e: unknown) {
                        const err = e as { detail?: string; message?: string }
                        lemonToast.error(err?.detail ?? err?.message ?? 'Failed to update retention')
                        throw e
                    }
                },
            },
        ],
    })),

    selectors({
        retentionDays: [
            (s) => [s.tracingConfig],
            (tracingConfig: TeamTracingConfigApi | null): number =>
                tracingConfig?.retention_days ?? TRACES_RETENTION_DEFAULT_DAYS,
        ],
        retentionLastUpdated: [
            (s) => [s.tracingConfig],
            (tracingConfig: TeamTracingConfigApi | null): string | null =>
                tracingConfig?.retention_last_updated ?? null,
        ],
    }),

    afterMount(({ actions }) => {
        actions.loadTracingConfig()
    }),
])
